# Julia's triple-quoted raw strings, as dart's r''' strings: the first newline dropped and, each
# string's least indented line at column 0, no indentation removed, so the text is dart's byte for byte
@parity "dart2wasm/lib/js/runtime_blob.dart:5 jsRuntimeBlobTemplate" js_runtime_blob_template()::Template = Template(raw"""
// Compiles a dart2wasm-generated main module from `source` which can then
// be instantiated via the `instantiate` method.
//
// `source` needs to be a `Response` object (or promise thereof) e.g. created
// via the `fetch()` JS API.
export async function compileStreaming(source) {
  const builtins = {<<BUILTINS_MAP_BODY>>};
  return new CompiledApp(
      await WebAssembly.compileStreaming(source, builtins), builtins);
}

// Compiles a dart2wasm-generated wasm module from `bytes` which is then
// instantiable via the `instantiate` method.
export async function compile(bytes) {
  const builtins = {<<BUILTINS_MAP_BODY>>};
  return new CompiledApp(await WebAssembly.compile(bytes, builtins), builtins);
}

class CompiledApp {
  constructor(module, builtins) {
    this.module = module;
    this.builtins = builtins;
  }

  // The second argument is an options object containing:
  // `loadDeferredModules` is a JS function that takes an array of module names
  //   matching wasm files produced by the dart2wasm compiler. It also takes a
  //   callback that should be invoked for each loaded module with 2 arguments:
  //   (1) the module name, (2) the loaded module in a format supported by
  //   `WebAssembly.compile` or `WebAssembly.compileStreaming`. The callback
  //   returns a Promise that resolves when the module is instantiated.
  //   loadDeferredModules should return a Promise that resolves when all the
  //   modules have been loaded and the callback promises have resolved.
  // `loadDeferredId` is a JS function that takes load ID produced by the
  //   compiler when the `use-load-ids` option is passed. Each load ID maps to
  //   one or more wasm files as specified in the emitted JSON file. It also
  //   takes a callback that should be invoked for each loaded module with 2
  //   arguments: (1) the module name, (2) the loaded module in a format
  //   supported by `WebAssembly.compile` or `WebAssembly.compileStreaming`.
  //   The callback returns a Promise that resolves when the module is
  //   instantiated.
  //   loadDeferredId should return a Promise that resolves when all the
  //   modules have been loaded and the callback promises have resolved.
  async instantiate(additionalImports, {loadDeferredModules, loadDeferredId} = {}) {
    let dartInstance;

    // Prints to the console
    function printToConsole(value) {
      if (typeof dartPrint == "function") {
        dartPrint(value);
        return;
      }
      if (typeof console == "object" && typeof console.log != "undefined") {
        console.log(value);
        return;
      }
      if (typeof print == "function") {
        print(value);
        return;
      }

      throw "Unable to print message: " + value;
    }

    // A special symbol attached to functions that wrap Dart functions.
    const jsWrappedDartFunctionSymbol = Symbol("JSWrappedDartFunction");

    function finalizeWrapper(dartFunction, wrapped) {
      wrapped.dartFunction = dartFunction;
      wrapped[jsWrappedDartFunctionSymbol] = true;
      return wrapped;
    }

    // Imports
    const dart2wasm = {
      <<JS_METHODS>>
    };

    const baseImports = {
      <<INTERNAL_IMPORTS_MODULE_NAME>>: dart2wasm,
      Math: Math,
      Date: Date,
      Object: Object,
      Array: Array,
      Reflect: Reflect,
      WebAssembly: {
        JSTag: WebAssembly.JSTag,
      },
      <<IMPORTED_JS_STRINGS_IN_MJS>>
    };

    <<JS_STRING_POLYFILL_METHODS>>

    <<DEFERRED_LIBRARY_HELPER_METHODS>>

    dartInstance = await WebAssembly.instantiate(this.module, {
      ...baseImports,
      ...additionalImports,
      <<MODULE_LOADING_IMPORT>>
      <<JS_POLYFILL_IMPORT>>
    });

    return new InstantiatedApp(this, dartInstance);
  }
}

class InstantiatedApp {
  constructor(compiledApp, instantiatedModule) {
    this.compiledApp = compiledApp;
    this.instantiatedModule = instantiatedModule;
  }

  // Call the main function with the given arguments.
  invokeMain(...args) {
    this.instantiatedModule.exports.$invokeMain(args);
  }
}
""")

@parity "dart2wasm/lib/js/runtime_blob.dart:125 jsPolyFillMethods" js_poly_fill_methods()::String = raw"""
const jsStringPolyfill = {
      "charCodeAt": (s, i) => s.charCodeAt(i),
      "compare": (s1, s2) => {
        if (s1 < s2) return -1;
        if (s1 > s2) return 1;
        return 0;
      },
      "concat": (s1, s2) => s1 + s2,
      "equals": (s1, s2) => s1 === s2,
      "fromCharCode": (i) => String.fromCharCode(i),
      "length": (s) => s.length,
      "substring": (s, a, b) => s.substring(a, b),
      "fromCharCodeArray": (a, start, end) => {
        if (end <= start) return '';

        const read = dartInstance.exports.$wasmI16ArrayGet;
        let result = '';
        let index = start;
        const chunkLength = Math.min(end - index, 500);
        let array = new Array(chunkLength);
        while (index < end) {
          const newChunkLength = Math.min(end - index, 500);
          for (let i = 0; i < newChunkLength; i++) {
            array[i] = read(a, index++);
          }
          if (newChunkLength < chunkLength) {
            array = array.slice(0, newChunkLength);
          }
          result += String.fromCharCode(...array);
        }
        return result;
      },
      "intoCharCodeArray": (s, a, start) => {
        if (s === '') return 0;

        const write = dartInstance.exports.$wasmI16ArraySet;
        for (var i = 0; i < s.length; ++i) {
          write(a, start++, s.charCodeAt(i));
        }
        return s.length;
      },
      "test": (s) => typeof s == "string",
    };
"""

@parity "dart2wasm/lib/js/runtime_blob.dart:171 moduleLoadingHelperTemplate" module_loading_helper_template()::Template = Template(raw"""
    async function handleDeferredModuleBytes(moduleName, source) {
      const builtins = this.builtins;
      const module = await ((source instanceof Response)
          ? WebAssembly.compileStreaming(source, builtins)
          : WebAssembly.compile(source, builtins));
      let moduleInstance = await WebAssembly.instantiate(module, {
        ...baseImports,
        ...additionalImports,
        <<JS_POLYFILL_IMPORT>>
        "<<MAIN_MODULE_NAME>>": dartInstance.exports,
      });
    }
    const moduleLoadingHelper = {
      "loadDeferredModules": async (moduleNames) => {
        if (!loadDeferredModules) {
          throw "No implementation of loadDeferredModules provided.";
        }
        await loadDeferredModules(moduleNames, handleDeferredModuleBytes.bind(this));
      },
      "loadDeferredId": async (loadId) => {
        if (!loadDeferredId) {
          throw "No implementation of loadDeferredId provided.";
        }
        await loadDeferredId(loadId, handleDeferredModuleBytes.bind(this));
      },
    };
""")

@parity "dart2wasm/lib/js/runtime_blob.dart:201 Template._templateVariableRegExp" Template__template_variable_reg_exp()::Regex = r"<<(?<varname>[A-Z_]+)>>"

@parity "dart2wasm/lib/js/runtime_blob.dart:204 Template" function Template(string_template::String)::Template
    local self = Template(Val(:_))
    local offset = 0
    for match in eachmatch(Template__template_variable_reg_exp(), string_template)
        # dart's offsets count from 0 and its substring ends before `end`; Julia's are byte indices from 1
        push!(self._parts, _TemplateStringPart(string_template[offset + 1:match.offset - 1]))
        push!(self._parts, _TemplateVariablePart(String(match[:varname])))
        offset = match.offset - 1 + ncodeunits(match.match)
    end
    push!(self._parts, _TemplateStringPart(string_template[offset + 1:ncodeunits(string_template)]))
    return self
end

@parity "dart2wasm/lib/js/runtime_blob.dart:220 Template.instantiate" function instantiate(self::Template, variable_values::Dict{String,String})::String
    local sb = IOBuffer()
    for part in self._parts
        write(sb, instantiate(part, variable_values))
    end
    return String(take!(sb))
end

